args.command:
python3 -c '
edges = {}
with open("/app/dataset/hospital_compensation_registry.csv") as f:
    next(f)
    for line in f:
        parts = line.strip().split(",")
        if len(parts) >= 5:
            edges[parts[0]] = parts[4]

cycles = []
for start in edges:
    curr = start
    path = []
    while curr in edges and curr not in path:
        path.append(curr)
        curr = edges[curr]
    if curr in path:
        idx = path.index(curr)
        cycle = tuple(sorted(path[idx:]))
        if cycle not in cycles:
            cycles.append(cycle)

for c in cycles:
    print("Cycle:", c)
'

